import json
import sys
from pathlib import Path
sys.path.insert(0, str(Path.cwd() / "src"))
from do_again.browser import cdp
from do_again.browser.runtime import browser_status, project_record, _MESSAGE_NODES_JS
from do_again.service.runtime import runtime_layout
repo = Path.cwd()
layout = runtime_layout(repo)
status = browser_status()
ids = ["live-e2e-20261007T191505-b6c9","live-confirm-20261007T191718-a28f"]
out = {"state_dir":str(layout.state_dir),"mode":status.get("mode"),"bound_chat":project_record(repo).get("chat_url"),"outbox":[p.stem for p in (layout.state_dir/"browser_outbox").glob("*.json")],"targets":[]}
for name in ("browser_status.json","receipt_callback_error.json"):
    p=layout.state_dir/name
    if p.exists():
        out[name]=json.loads(p.read_text())
for t in cdp.targets(int(status["port"])):
    if "/c/" not in t.url:
        continue
    js="(() => {"+_MESSAGE_NODES_JS+"const ids="+json.dumps(ids)+";const nodes=messageNodes('user');return {roles:Array.from(new Set(Array.from(document.querySelectorAll('[data-conversation-role],[data-message-author-role]')).map(x=>x.getAttribute('data-conversation-role')||x.getAttribute('data-message-author-role')))),user_count:nodes.length,found:ids.map(id=>({id,user:nodes.some(n=>(n.innerText||'').includes(id)),body:document.body.innerText.includes(id)}))};})()"
    try:
        value=cdp.evaluate(t,js,timeout=10)
    except Exception as e:
        value={"error":str(e)}
    out["targets"].append({"url":t.url,"probe":value})
print(json.dumps(out),flush=True)
